import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Автосервис: онлайн-запись на посты, история обслуживания и кабинет клиента"}>
      <p>{"Автосервис в Нижнем Новгороде: четыре подъёмника, шиномонтаж и мастер-приёмщик. Сейчас записываем по телефону в тетрадь, в сезон смены шин теряем клиентов. Хотим онлайн-запись: клиент выбирает услугу (ТО, диагностика подвески, шиномонтаж, замена масла), марку и модель машины, видит свободное время на постах и записывается. Длительность зависит от услуги, шиномонтаж идёт на отдельный пост. За день приходит напоминание, перенести запись можно не позже чем за три часа. В личном кабинете клиент видит свои машины, записи и историю работ с пробегом. Мастер-приёмщик видит всё расписание, записывает клиентов по звонку и закрывает визит: что сделано, пробег, сумма. Механики видят только свои работы на день. На сайте — услуги с ценами «от», акции сезона и контакты. Отзывы с площадок собирает наш маркетолог клиент, его телеграм клиент. Онлайн-оплата пока не нужна."}</p>
      <ul>
        <li>{"Запись на свободное время"}</li>
        <li>{"Напоминание за день"}</li>
        <li>{"Кабинет клиента с историей"}</li>
        <li>{"Перенос записи"}</li>
      </ul>
      <p>{"Механик видит только свои работы"}</p>
      <p>{"Приёмщик записывает по звонку"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
